insert into public.quick_reference_sections (id,body,version)
values ('preop-urgency','- **Emergency:** Immediate threat to life or limb; generally less than 2 hours available ([AHA/ACC guideline, section 1.5](https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285)).
- **Urgent:** Threat to life or limb; generally 2 to less than 24 hours available ([AHA/ACC guideline, section 1.5](https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285)).
- **Time-sensitive:** May be delayed up to 3 months for evaluation and management without adversely affecting outcomes ([AHA/ACC guideline, section 1.5](https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285)).
- **Elective:** Can be delayed to complete appropriate evaluation and treatment ([AHA/ACC guideline, section 1.5](https://www.ahajournals.org/doi/10.1161/CIR.0000000000001285)).','2026-09-27')
on conflict (id) do update set body=excluded.body,version=excluded.version,updated_at=now();

